import React, { useState } from "react";
import { AddCar } from "../../services/ApiCar";

export default function CardAddVoiture() {
  const [newCar, setNewCar] = useState({
    matricule: "",
    model: "",
    Libelle: "",
    prix: "",
    Prix_Jour: "",
    Couleur: "",
    voiture_image: null,
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewCar({ ...newCar, [name]: value });
  };

  const handleImageChange = (e) => {
    setNewCar({ ...newCar, voiture_image: e.target.files[0] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const formData = new FormData();
      for (const key in newCar) {
        formData.append(key, newCar[key]);
      }

      await AddCar(formData);
      alert("🚗 Voiture ajoutée avec succès !");
    } catch (error) {
      console.error("Erreur lors de l'ajout :", error);
      alert("❌ Une erreur est survenue.");
    }
  };

  return (
    <div className="p-6 bg-white rounded shadow">
      <form onSubmit={handleSubmit}>
        {/* Exemple d'un champ */}
        <input
          type="text"
          name="matricule"
          placeholder="Matricule"
          value={newCar.matricule}
          onChange={handleChange}
          className="mb-3 p-2 border rounded w-full"
        />

        {/* Autres champs comme model, libelle, prix, etc. */}
        <input
          type="text"
          name="model"
          placeholder="Model"
          value={newCar.model}
          onChange={handleChange}
          className="mb-3 p-2 border rounded w-full"
        />

        {/* Image */}
        <input
          type="file"
          name="voiture_image"
          onChange={handleImageChange}
          className="mb-3 p-2 border rounded w-full"
        />

        {/* Bouton d'envoi */}
        <button
          type="submit"
          className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
        >
          Add Car
        </button>
      </form>
    </div>
  );
}
